/**
 * The share viewer's Markdown renderer.
 *
 * GENERATED by scripts/build-share.mjs from src/editor/markdown/render.ts
 * (bundled with its pure dependencies — math-shell, escape, the safe-href
 * gate — and tree-shaken free of everything else; KaTeX never reaches this
 * island). DO NOT EDIT. Any change to the rendered subset belongs in the
 * source file; regenerate with `npm run build:share`. The drift test in
 * src/share-sanitizer.test.ts regenerates this in memory and fails on any
 * divergence.
 */
// src/lib/escape.ts
function escapeHtml(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
function escapeHtmlAttr(value) {
  return value.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

// src/editor/math-shell.ts
var MATH_CLASS = "padify-math";
function buildMathShell(latex) {
  return `<span class="${MATH_CLASS}" data-latex="${escapeHtmlAttr(latex)}" contenteditable="false"></span>`;
}

// src/editor/storage-subset.ts
var SAFE_HREF_PATTERN = /^(https?:|mailto:|#|\/)/i;
function sanitizeHref(raw) {
  const href = raw.trim();
  return href.length > 0 && SAFE_HREF_PATTERN.test(href) ? href : null;
}

